     },\n        Wait(1),\n        MessageBox{message=\"Baby T's Reflection: Even though I have lived in Boudler Bay my whole life, I had to learn about the Light of Mobius from Tails!\"},\n        PlayAudio(\"music\", \"sonicsad\", 1, true, true),\n        Animate(sprites.tails.sprite, \"sadright\"),\n        Animate(refsprites.tails.sprite, \"sadright\"),\n        MessageBox{message=\"Baby T's Reflection: I don't know anything about Freedom Fighting. {p60}I'm a runt--even for a Terrapod my age!\"},\n        MessageBox{message=\"Baby T's Reflection: Any other Terrapod would be a better choice to face Robotnik than me!\"},\n        Animate(sprites.babyt.sprite, \"saddown\"),\n        Animate(refsprites.babyt.sprite, \"idleup\"),\n        Wait(1),\n        Animate(sprites.b.sprite, \"idleright\"),\n        Animate(refsprites.b.sprite, \"idleright\"),\n        MessageBox{message=\"B: Don't listen to that dark reflection, son! {p60}You have more than proven yourself to us!\"},\n        Wait(1),\n        MessageBox{message=\"Tails' Reflection: I shouldn't even be here! {p60}I'm not even a real Freedom Fighter.\"},\n        Animate(sprites.b.sprite, \"idleup\"),\n        Animate(refsprites.b.sprite, \"idledown\"),\n        Animate(sprites.tails.sprite, \"idleup\"),\n        Animate(refsprites.tails.sprite, \"idledown\"),\n        MessageBox{message=\"Tails' Reflection: I'm just going to make a dumb wish and screw everything up...\"},\n        Animate(sprites.tails.sprite, \"saddown\"),\n        Animate(refsprites.tails.sprite, \"idleup\"),\n        Wait(1),\n        Animate(sprites.b.sprite, \"idleright\"),\n        Animate(refsprites.b.sprite, \"idleright\"),\n        MessageBox{message=\"B: That's not true! {p60}Tails, you remind me so much of my dear R...\"},\n        MessageBox{message=\"B: You are passionate, courageous, smart as a whip, and you have a big heart! {p60}If that does not make a great Freedom Fighter, I don't know what does!\"},\n        Wait(1),\n        Animate(sprites.b.sprite, \"pose\"),\n        Animate(refsprites.b.sprite, \"idleup\"),\n        MessageBox{message=\"B: This is some kind of trial to test of our resolve, I'm sure of it...\"},\n        Wait(1),\n        MessageBox{message=\"B's Reflection: I am no adventurer... {p60}I was barely able to leave a small, hidden corner of Robotropolis...\"},\n        Animate(sprites.b.sprite, \"idleup\"),\n        Animate(refsprites.b.sprite, \"idledown\"),\n        MessageBox{message=\"B's Reflection: I abandoned my family in Robotropolis,\\nand now I've lead these children to their grave...\"},\n        Animate(sprites.b.sprite, \"pose\"),\n        Animate(refsprites.b.sprite, \"idleup\"),\n        MessageBox{message=\"B: ...\"},\n        Animate(sprites.tails.sprite, \"sadleft\"),\n        Animate(refsprites.tails.sprite, \"sadleft\"),\n        Animate(sprites.babyt.sprite, \"sadleft\"),\n        Animate(refsprites.babyt.sprite, \"sadleft\"),\n        MessageBox{message=\"B's Reflection: These kids deserve better than me...{p60} What if I forget something important or suddenly become inoperable at a critical moment?\"},\n        MessageBox{message=\"B's Reflection: How can someone like that be relied on?...\"},\n        AudioFade(\"music\", 1, 0, 1),\n        Wait(1),\n        Animate(sprites.tails.sprite, \"idleleft\"),\n        Animate(refsprites.tails.sprite, \"idleleft\"),\n        MessageBox{message=\"Tails: It's ok to be afraid, B. {p60}Sonic taught me that even heroes get scared sometimes.\"},\n        Animate(sprites.babyt.sprite, \"idleleft\"),\n        Animate(refsprites.babyt.sprite, \"idleleft\"),\n        MessageBox{message=\"Baby T: Yeah! {p60}And remember when you saved us from my uncle? {p60}If it wasn't for you, we woulda been worm food.\"},\n        Animate(sprites.b.sprite, \"idledown\"),\n        Animate(refsprites.b.sprite, \"idleup\"),\n        PlayAudio(\"music\", \"bleaves2\", 1, true),\n        MessageBox{message=\"B: Thanks kids. {p60}We can't let these negative thoughts get us down!\"},\n        Animate(sprites.tails.sprite, \"pose\"),\n        Animate(refsprites.tails.sprite, \"idleup\"),\n        MessageBox{message=\"Tails: Yeah! {p60}Go take a hike-- {p30}uh-- {p30}me!\"},\n        Animate(sprites.babyt.sprite, \"victory\"),\n        Animate(refsprites.babyt.sprite, \"idleup\"),\n        MessageBox{message=\"Baby T: Beat it, Fake Baby T!\"},\n        Wait(1),\n        Do(function()\n            sprites.tails.sprite:setFadeWhite(1)\n            sprites.b.sprite:setFadeWhite(1)\n            sprites.babyt.sprite:setFadeWhite(1)\n            refsprites.tails.sprite:setFadeWhite(1)\n            refsprites.b.sprite:setFadeWhite(1)\n            refsprites.babyt.sprite:setFadeWhite(1)\n        end),\n        Wait(2),\n        Do(function()\n            local tx, ty = sprites.tails.x, sprites.tails.y\n            local btx, bty = sprites.babyt.x, sprites.babyt.y\n            local bx, by = sprites.b.x, sprites.b.y\n\n            sprites.tails.x = refsprites.tails.x\n            sprites.tails.y = refsprites.tails.y\n            sprites.b.x = refsprites.b.x\n            sprites.b.y = refsprites.b.y\n            sprites.babyt.x = refsprites.babyt.x\n            sprites.babyt.y = refsprites.babyt.y\n\n            refsprites.tails.x = tx\n            refsprites.tails.y = ty\n            refsprites.b.x = bx\n            refsprites.b.y = by\n            refsprites.babyt.x = btx\n            refsprites.babyt.y = bty\n        end),\n\n        Parallel {\n            Ease(refsprites.b.sprite.color, 4, 0, 0.5),\n            Ease(refsprites.babyt.sprite.color, 4, 0, 0.5),\n            Ease(refsprites.tails.sprite.color, 4, 0, 0.5),\n            Ease(self.scene.player, \"y\", function() return self.scene.player.y - 224 end, 0.5)\n        },\n        Do(function()\n            refsprites.tails:remove()\n            refsprites.babyt:remove()\n            refsprites.b:remove()\n            reflection:remove()\n            self.scene:findLayer(\"clipwaterfall\").opacity = 0\n        end),\n\n        walkin\n    }\nend"
